static int p2d89_emit_lines_incomplete_figures(P2D89_ShapeId id,const P2D89_Provider *p){static const p2d89_q14 sq[]={-16384,-16384,16384,-16384,16384,16384,-16384,16384};static const p2d89_q14 rc[]={-16384,-10240,16384,-10240,16384,10240,-16384,10240};static const p2d89_q14 tr[]={0,-16384,14189,8192,-14189,8192};static const p2d89_q14 dm[]={0,-16384,16384,0,0,16384,-16384,0};if(id==P2D89_SHAPE_OPEN_SQUARE)return p2d89_i_poly(sq,4U,0,p);if(id==P2D89_SHAPE_OPEN_RECTANGLE)return p2d89_i_poly(rc,4U,0,p);if(id==P2D89_SHAPE_OPEN_TRIANGLE)return p2d89_i_poly(tr,3U,0,p);if(id==P2D89_SHAPE_OPEN_DIAMOND)return p2d89_i_poly(dm,4U,0,p);if(id==P2D89_SHAPE_OPEN_CIRCLE||id==P2D89_SHAPE_C_SHAPE)return p2d89_i_arc_3q(p);if(id==P2D89_SHAPE_OPEN_ELLIPSE){p2d89_q14 kx,ky;kx=p2d89_mul_q14(16384,P2D89_KAPPA);ky=p2d89_mul_q14(10240,P2D89_KAPPA);if(!p2d89_i_move(p,16384,0))return 0;if(!p2d89_i_cubic(p,16384,ky,kx,10240,0,10240))return 0;if(!p2d89_i_cubic(p,(p2d89_q14)-kx,10240,-16384,ky,-16384,0))return 0;return p2d89_i_cubic(p,-16384,(p2d89_q14)-ky,(p2d89_q14)-kx,-10240,0,-10240);}if(id==P2D89_SHAPE_U_SHAPE){if(!p2d89_i_move(p,-12288,-12288))return 0;if(!p2d89_i_line(p,-12288,4096))return 0;if(!p2d89_i_cubic(p,-12288,14336,12288,14336,12288,4096))return 0;return p2d89_i_line(p,12288,-12288);}if(id==P2D89_SHAPE_BROKEN_CIRCLE){if(!p2d89_i_move(p,16384,0))return 0;if(!p2d89_i_cubic(p,16384,9048,9048,16384,0,16384))return 0;if(!p2d89_i_cubic(p,-9048,16384,-16384,9048,-16384,0))return 0;if(!p2d89_i_move(p,-14336,-8192))return 0;if(!p2d89_i_cubic(p,-8192,-14336,-2048,-16384,4096,-14336))return 0;return p2d89_i_cubic(p,10240,-12288,14336,-6144,16384,0);}return 0;}
